#include "GameSessionTestAccess.h"
#include "tiny2d_game/SessionController.h"
#include "vfx/CombatVFX.h"
using namespace tiny2d_game;using namespace tiny2d_vfx;using A=GameSessionTestAccess;
namespace tiny2d_vfx {
struct CombatVFXTestAccess {static void add(CombatVFX& v,EffectKind k){v.add({{80,0},{},0,k==EffectKind::Death?.3:k==EffectKind::Hit?.15:.08,k});}};
}
static unsigned count(const CombatVFX& v,EffectKind k){unsigned n=0;for(auto e:v.effects())n+=e.life>0&&e.kind==k;return n;}
static void same(const CombatVFX& a,const CombatVFX& b){check(a.active()==b.active()&&a.dropped()==b.dropped(),"same counters");for(unsigned i=0;i<a.capacity;++i){auto x=a.effects()[i],y=b.effects()[i];check(x.kind==y.kind&&x.life==y.life&&x.age==y.age&&x.createdSequence==y.createdSequence&&x.p.x==y.p.x&&x.p.y==y.p.y,"same slots");}auto ids=a.scene().objects(),js=b.scene().objects();for(unsigned i=0;i<ids.size();++i){auto x=a.scene().find(ids[i]),y=b.scene().find(js[i]);check(x->enabled==y->enabled,"same enabled");if(x->enabled)check(x->transform.position.x==y->transform.position.x&&x->transform.position.y==y->transform.position.y&&x->sprite->a==y->sprite->a&&x->sprite->size.x==y->sprite->size.x&&x->sprite->r==y->sprite->r,"same sprites");}}
int main(){try{
 for(auto existing:{EffectKind::Trail,EffectKind::Hit,EffectKind::Death})for(auto incoming:{EffectKind::Trail,EffectKind::Hit,EffectKind::Death}){CombatVFX v;for(unsigned i=0;i<v.capacity;++i)CombatVFXTestAccess::add(v,existing);auto sequence=v.effects()[0].createdSequence;CombatVFXTestAccess::add(v,incoming);check(v.active()==128&&v.dropped()==1,"one rejection or eviction");check((v.effects()[0].createdSequence!=sequence)==(incoming>=existing),"priority and oldest eviction");}
 CombatVFX mixed;CombatVFXTestAccess::add(mixed,EffectKind::Hit);for(int i=1;i<128;++i)CombatVFXTestAccess::add(mixed,EffectKind::Trail);CombatVFXTestAccess::add(mixed,EffectKind::Death);check(mixed.effects()[0].kind==EffectKind::Hit&&mixed.effects()[1].kind==EffectKind::Death,"lowest priority before oldest");mixed.update(1);auto drops=mixed.dropped();CombatVFXTestAccess::add(mixed,EffectKind::Trail);check(mixed.dropped()==drops&&mixed.effects()[0].life>0,"first free without drop");
 for(bool kill:{false,true}){GameSession g(quiet());CombatVFX a,b;for(int i=0;i<64;++i)A::shot(g,{-1000,float(i*20)},1000);for(int i=0;i<3;++i){g.fixedUpdate();a.consume(g);b.consume(g);}check(a.active()==128,"64 projectile saturation");A::enemy(g,{80,0});A::shot(g,{80,0});if(kill)A::shot(g,{80,0});g.fixedUpdate();a.consume(g);b.consume(g);auto kind=kill?EffectKind::Death:EffectKind::Hit;check(count(a,kind)==1,"real feedback inserted");auto hits=g.hitCount(),kills=g.killCount();
  double life=kill?.3:.15;for(int i=0;i<8;++i){a.update(life/10);b.update(life/10);g.fixedUpdate();a.consume(g);b.consume(g);a.present(g,320,240);b.present(g,320,240);check(count(a,kind)==1,"protected from continuous trails");same(a,b);}check(g.hitCount()==hits&&g.killCount()==kills,"no repeated score");a.update(life*.21);check(count(a,kind)==0,"normal expiry");}
 GameSession history(quiet());for(int i=0;i<200;++i){A::enemy(history,{80,0});A::shot(history,{80,0});A::shot(history,{80,0});history.fixedUpdate();}CombatVFX lost;lost.consume(history);check(lost.dropped()==history.eventSequence()-lost.active(),"history loss plus exactly one per rejected or evicted effect");auto prior=lost.dropped();lost.consume(history);check(lost.dropped()==prior,"no double counting");
 SessionController s(quiet(),{1});CombatVFX v;A::enemy(s.game(),{80,0});A::shot(s.game(),{80,0});s.game().fixedUpdate();v.consume(s.game());check(v.active()==1,"old feedback");s.restartKey(true);v.consume(s.game());check(!v.active()&&!v.dropped(),"restart resets");A::enemy(s.game(),{80,0});A::shot(s.game(),{80,0});s.game().fixedUpdate();v.consume(s.game());check(v.effects()[0].createdSequence==1,"new insertion sequence");
}catch(const std::exception&e){std::cerr<<e.what();return 1;}}
